import sys
from click import command, echo_via_pager
from click.testing import CliRunner

@command()
def cli():
    echo_via_pager("Hello, Click!")

runner = CliRunner()
with runner.isolation():
    try:
        cli.main(args=[])
    finally:
        print("sys.stdout closed in finally:", sys.stdout.closed)
        try:
            sys.stdout.flush()
        except Exception as e:
            print("flush raised:", e)

