from click import command, echo_via_pager
from click.testing import CliRunner

@command()
def cli():
    echo_via_pager("Hello, Click!")

@command()
def cli_file():
    import click
    with click.get_pager_file() as pager:
        pager.write("Hello, Pager File!\n")

for cmd in (cli, cli_file):
    res = CliRunner().invoke(cmd)
    print(cmd.name, repr(res.output))

